PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?agentId
       (SUM(DISTINCT ?lossAmt) AS ?totalLoss)
       (SUM(DISTINCT ?premAmt) AS ?totalPremium)
       ((SUM(DISTINCT ?lossAmt) / SUM(DISTINCT ?premAmt)) AS ?lossRatio)
WHERE {
  SERVICE <mapped> {
    ?policy a ins:Policy ;
            ins:policyNumber ?policyNumber ;
            ins:soldByAgent ?agent .

    ?agent ins:agentId ?agentId .

    ?coverage a ins:PolicyCoverageDetail ;
              ins:hasPolicy ?policy ;
              ins:hasPremiumAmount ?premium .

    ?premium ins:premiumAmount ?premAmt .

    OPTIONAL {
      ?claim a ins:Claim ;
             ins:against ?coverage .

      OPTIONAL {
        ?claim ins:hasLossPayment ?lp .
        ?lp ins:lossPaymentAmount ?lpAmt .
      }

      OPTIONAL {
        ?claim ins:hasLossReserve ?lr .
        ?lr ins:lossReserveAmount ?lrAmt .
      }

      BIND((COALESCE(?lpAmt, 0) + COALESCE(?lrAmt, 0)) AS ?lossAmt)
    }
  }
}
GROUP BY ?policyNumber ?agentId
ORDER BY ?policyNumber ?agentId

PREFIX ins: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?policyNumber ?effectiveDate ?expirationDate
WHERE {
  SERVICE <mapped> {
    ?policy a ins:Policy ;
            ins:policyNumber ?policyNumber ;
            ins:policyEffectiveDate ?effectiveDate ;
            ins:policyExpirationDate ?expirationDate .
  }
}

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolder ?premiumAmountPaid ?agent ?lossPaymentAmount ?lossReserveAmount ?expensePaymentAmount ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber ;
           ins:against ?pcd .

    ?pcd ins:hasPolicy ?policy ;
         ins:hasPremiumAmount ?premium .

    ?policy ins:policyNumber ?policyNumber ;
            ins:hasPolicyHolder ?policyHolderRes ;
            ins:soldByAgent ?agentRes .

    ?policyHolderRes ins:policyHolderId ?policyHolder .
    ?premium ins:premiumAmount ?premiumAmountPaid .
    ?agentRes ins:agentId ?agent .

    OPTIONAL {
      ?claim ins:hasLossPayment ?lp .
      ?lp ins:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim ins:hasLossReserve ?lr .
      ?lr ins:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim ins:hasExpensePayment ?ep .
      ?ep ins:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim ins:hasExpenseReserve ?er .
      ?er ins:expenseReserveAmount ?expenseReserveAmount .
    }
  }
}

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?catastropheName ?policyNumber
       (SUM(?lossPaymentVal + ?lossReserveVal + ?expensePaymentVal + ?expenseReserveVal) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim .

    OPTIONAL {
      ?claim ins:hasCatastrophe ?cat .
      ?cat ins:catastropheName ?catastropheName .
    }

    ?claim ins:against ?pcd .
    ?pcd ins:hasPolicy ?policy .
    ?policy ins:policyNumber ?policyNumber .

    OPTIONAL {
      ?claim ins:hasLossPayment ?lp .
      ?lp ins:lossPaymentAmount ?lossPaymentRaw .
    }
    OPTIONAL {
      ?claim ins:hasLossReserve ?lr .
      ?lr ins:lossReserveAmount ?lossReserveRaw .
    }
    OPTIONAL {
      ?claim ins:hasExpensePayment ?ep .
      ?ep ins:expensePaymentAmount ?expensePaymentRaw .
    }
    OPTIONAL {
      ?claim ins:hasExpenseReserve ?er .
      ?er ins:expenseReserveAmount ?expenseReserveRaw .
    }

    BIND(COALESCE(xsd:decimal(?lossPaymentRaw), 0) AS ?lossPaymentVal)
    BIND(COALESCE(xsd:decimal(?lossReserveRaw), 0) AS ?lossReserveVal)
    BIND(COALESCE(xsd:decimal(?expensePaymentRaw), 0) AS ?expensePaymentVal)
    BIND(COALESCE(xsd:decimal(?expenseReserveRaw), 0) AS ?expenseReserveVal)
  }
}
GROUP BY ?catastropheName ?policyNumber
ORDER BY ?catastropheName ?policyNumber

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber ?claimNumber ?expensePaymentAmount
WHERE {
  SERVICE <mapped> {
    ?policy ins:soldByAgent ?agent ;
            ins:policyNumber ?policyNumber .

    ?agent ins:agentId ?agentId .

    ?coverage ins:hasPolicy ?policy .

    ?claim ins:against ?coverage ;
           ins:claimNumber ?claimNumber ;
           ins:hasExpensePayment ?expensePayment .

    ?expensePayment ins:expensePaymentAmount ?expensePaymentAmount .
  }
}
ORDER BY ?agentId ?policyNumber ?claimNumber ?expensePaymentAmount
